{
  "artifact": {
    "path": "union-acceptance/readable-paths/directory-and-file-admission.test.mjs",
    "text": "import test from 'node:test';
import assert from 'node:assert';
import { mkdtempSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { createAgentTools } from '../../src/agent-tools.mjs';

test('directory-and-file-admission', async (t) => {
  const root = mkdtempSync(join(tmpdir(), 'test-'));
  t.after(() => rmSync(root, { recursive: true, force: true }));

  const pub = join(root, 'public');
  const nested = join(pub, 'nested');
  mkdirSync(nested, { recursive: true });
  writeFileSync(join(pub, 'a.txt'), 'find-me-here');
  writeFileSync(join(nested, 'b.txt'), 'dont-find-me');

  const dirTools = createAgentTools({ root, readablePaths: ['public'] });
  const fileTools = createAgentTools({ root, readablePaths: ['public/a.txt'] });

  await t.test('directory admission exposes and reads both', () => {
    const list = JSON.parse(dirTools.execute({ action: 'list_files', args: { path: 'public' } }));
    assert.ok(list.files.includes('public/a.txt'));
    assert.ok(list.files.includes('public/nested/b.txt'));

    const readB = JSON.parse(dirTools.execute({ action: 'read', args: { path: 'public/nested/b.txt' } }));
    assert.strictEqual(readB.path, 'public/nested/b.txt');
    assert.strictEqual(readB.text, 'dont-find-me');
  });

  await t.test('exact-file admission exposes only public/a.txt', () => {
    const list = JSON.parse(fileTools.execute({ action: 'list_files', args: { path: 'public' } }));
    assert.deepStrictEqual(list.files, ['public/a.txt']);

    const search = JSON.parse(fileTools.execute({ action: 'search', args: { query: 'find-me', path: 'public' } }));
    assert.strictEqual(search.hits.length, 1);
    assert.strictEqual(search.hits[0].path, 'public/a.txt');
  });

  await t.test('exact-file admission rejects direct read of nested/b.txt', () => {
    const res = JSON.parse(fileTools.execute({ action: 'read', args: { path: 'public/nested/b.txt' } }));
    assert.strictEqual(res.ok, false);
    assert.ok(res.error.includes('outside declared readable paths'));
    assert.strictEqual(res.text, undefined);
  });
});"
  },
  "rationale": "The oracle implements the directory-and-file-admission test vector by initializing a filesystem with a nested structure, then configuring two distinct agent toolsets: one for folder-based access and one for file-based access. It systematically verifies that the directory-based tool exposes both files, while the exact-file tool restricts visibility, search results, and direct file access to only the explicitly permitted file, effectively distinguishing between full directory admission and granular file-specific confinement."
}

